#!/usr/bin/env python3
"""crc32sum.py - compute or verify CRC-32 checksums (polynomial 0xEDB88320).

Usage:
    crc32sum.py FILE [FILE ...]        print "checksum  filename" per file
    crc32sum.py -c MANIFEST            verify manifest, exit 1 on any failure
"""

import argparse
import sys

POLY = 0xEDB88320


def _make_table():
    table = []
    for i in range(256):
        crc = i
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ POLY
            else:
                crc >>= 1
        table.append(crc)
    return table


_TABLE = _make_table()


def crc32(data: bytes, crc: int = 0) -> int:
    """Table-driven CRC-32 (reflected, poly 0xEDB88320), zlib-compatible."""
    crc ^= 0xFFFFFFFF
    for byte in data:
        crc = _TABLE[(crc ^ byte) & 0xFF] ^ (crc >> 8)
    return crc ^ 0xFFFFFFFF


def compute_file(path):
    crc = 0
    with open(path, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            crc = crc32(chunk, crc)
    return crc


def cmd_checksum(paths):
    rc = 0
    for path in paths:
        try:
            crc = compute_file(path)
        except OSError as e:
            print(f"crc32sum.py: {path}: {e}", file=sys.stderr)
            rc = 1
            continue
        print(f"{crc:08x}  {path}")
    return rc


def cmd_verify(manifest_path):
    failed = False
    try:
        f = open(manifest_path, "r", encoding="utf-8")
    except OSError as e:
        print(f"crc32sum.py: {manifest_path}: {e}", file=sys.stderr)
        return 1
    with f:
        for lineno, line in enumerate(f, 1):
            line = line.rstrip("\n")
            if not line.strip():
                continue
            parts = line.split(None, 1)
            if len(parts) != 2:
                print(f"crc32sum.py: {manifest_path}:{lineno}: malformed line",
                      file=sys.stderr)
                failed = True
                continue
            expected, path = parts
            try:
                actual = f"{compute_file(path):08x}"
            except OSError as e:
                print(f"{path}: FAILED (open failed: {e})")
                failed = True
                continue
            if actual == expected.lower():
                print(f"{path}: OK")
            else:
                print(f"{path}: FAILED (expected {expected.lower()}, got {actual})")
                failed = True
    return 1 if failed else 0


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="crc32sum.py",
        description="Compute or verify CRC-32 (poly 0xEDB88320) checksums.")
    parser.add_argument("-c", "--check", metavar="MANIFEST",
                        help="verify CRC-32 manifests of the form 'checksum  filename'")
    parser.add_argument("files", nargs="*", help="files to checksum")
    args = parser.parse_args(argv)

    if args.check:
        return cmd_verify(args.check)
    if not args.files:
        parser.error("no files given (or use -c MANIFEST to verify a manifest)")
    return cmd_checksum(args.files)


if __name__ == "__main__":
    sys.exit(main())

